def new_catalog():
    result = []
    for ident,name,sector,industry,colors,font,radius,pad,advanced,blocks,source,summary,guidance,headline,offerings in RECIPES:
        primary,bg,surface,ink,muted,accent = colors
        url = ('https://www.ecomdesignawards.com/websites/' + source[4:] if source.startswith('eda:')
               else 'https://www.cssdesignawards.com/sites/' + source + '/')
        result.append(dict(id='local-'+ident,name=name,sector=sector,category='Editorial' if font=='serif' else 'Contemporary',industry=industry,
            introduced_version=2,source_url=url,summary=summary,guidance=guidance,
            tags=[sector,'local','original'],blueprint=blocks,
            tokens=dict(palette=dict(primary=primary,primaryDark=primary,deep=primary,bg=bg,surface=surface,ink=ink,muted=muted,accent=accent),
                type=dict(heading=font),shape=dict(radius=str(radius)+'px',button=str(min(radius,24))+'px'),
                layout=dict(pad=str(pad)+'px'),photos=dict(overlay='0.46'),advanced=advanced),
            enabled=True,version=1,updated=0,origin='local-catalog'))
    return result

